<?php
require_once '../includes/auth.php'; require_once '../config/config.php';
if (!isAdmin() && !isTeller()) { header('Location: dashboard.php'); exit; }
$pesan=null; $jenis='success';
if ($_SERVER['REQUEST_METHOD']==='POST' && isset($_POST['tutup_closing'])) {
    if (!isAdmin()) { $jenis='danger'; $pesan='Hanya Admin yang dapat menutup periode angsuran.'; }
    else try { layananValidasiToken(); $b=trim($_POST['bulan']??''); $h=tutupClosingAngsuran($db,$b,$_SESSION['user_id'],trim($_POST['catatan']??'')); $pesan='Periode '.htmlspecialchars($b).' berhasil dikunci ('.$h['jumlah_pembayaran'].' pembayaran, Rp '.number_format($h['total_pembayaran'],0,',','.').').'; } catch(Exception $e) { $jenis='danger'; $pesan=$e->getMessage(); }
}
$closing=closingTabelAda($db)?$db->query("SELECT c.*,u.nama_lengkap FROM closing_angsuran_bulanan c LEFT JOIN users u ON u.id=c.ditutup_oleh ORDER BY c.bulan DESC")->fetchAll(PDO::FETCH_ASSOC):[];
?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Closing Angsuran</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.1.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.0.0/css/all.min.css" rel="stylesheet"></head><body><?php include '../includes/header.php'; ?><div class="container-fluid"><div class="row"><?php include '../includes/sidebar.php'; ?><main class="col-md-9 ms-sm-auto col-lg-10 px-md-4 py-4"><h3><i class="fas fa-lock me-2"></i>Closing Angsuran Bulanan</h3><?php if($pesan): ?><div class="alert alert-<?php echo $jenis; ?>"><?php echo $pesan; ?></div><?php endif; ?><div class="alert alert-info">Setelah periode dikunci, pembayaran dan pembatalan untuk tanggal dalam bulan tersebut tidak dapat diubah.</div><?php if(isAdmin()): ?><form method="post" class="card card-body mb-4"><?php echo layananToken(); ?><input type="hidden" name="tutup_closing" value="1"><div class="row g-3 align-items-end"><div class="col-md-3"><label class="form-label">Bulan yang ditutup</label><input type="month" name="bulan" class="form-control" value="<?php echo date('Y-m'); ?>" max="<?php echo date('Y-m'); ?>" required></div><div class="col-md-6"><label class="form-label">Catatan</label><input name="catatan" class="form-control" maxlength="500" placeholder="Contoh: Closing Oktober 2026"></div><div class="col-md-3"><button class="btn btn-primary w-100" onclick="return confirm('Kunci periode ini?')"><i class="fas fa-lock me-1"></i>Kunci Periode</button></div></div></form><?php endif; ?><div class="card"><div class="card-header">Riwayat Closing dan Progres Bulanan</div><div class="table-responsive"><table class="table table-striped mb-0"><thead><tr><th>Bulan</th><th>Status</th><th>Jumlah Pembayaran</th><th>Total Angsuran</th><th>Ditutup Oleh</th><th>Waktu</th><th>Catatan</th></tr></thead><tbody><?php if(!$closing): ?><tr><td colspan="7" class="text-center text-muted">Belum ada periode yang ditutup.</td></tr><?php else: foreach($closing as $row): ?><tr><td><?php echo date('m/Y',strtotime($row['bulan'].'-01')); ?></td><td><span class="badge bg-<?php echo $row['status']==='terkunci'?'success':'secondary'; ?>"><?php echo ucfirst($row['status']); ?></span></td><td><?php echo number_format((int)$row['jumlah_pembayaran'],0,',','.'); ?></td><td>Rp <?php echo number_format((float)$row['total_pembayaran'],0,',','.'); ?></td><td><?php echo htmlspecialchars($row['nama_lengkap']?:'-'); ?></td><td><?php echo date('d/m/Y H:i',strtotime($row['ditutup_at'])); ?></td><td><?php echo htmlspecialchars($row['catatan']?:'-'); ?></td></tr><?php endforeach; endif; ?></tbody></table></div></div></main></div></div></body></html>
